function solve(s) {
  const n = s.length;
  const out = [];
  const ok = (seg) => {
    if (seg.length === 0 || seg.length > 3) return false;
    if (seg.length > 1 && seg[0] === "0") return false;
    return Number(seg) <= 255;
  };
  for (let a = 1; a <= 3; a++) {
    for (let b = 1; b <= 3; b++) {
      for (let c = 1; c <= 3; c++) {
        const d = n - a - b - c;
        if (d < 1 || d > 3) continue;
        const parts = [s.slice(0, a), s.slice(a, a + b), s.slice(a + b, a + b + c), s.slice(a + b + c)];
        if (parts.every(ok)) out.push(parts.join("."));
      }
    }
  }
  out.sort();
  return out;
}

function solve(s) {
  const n = s.length;
  const out = [];
  const parts = [];
  function dfs(start) {
    if (parts.length === 4) {
      if (start === n) out.push(parts.join("."));
      return;
    }
    for (let len = 1; len <= 3; len++) {
      if (start + len > n) break;
      const seg = s.slice(start, start + len);
      if (seg.length > 1 && seg[0] === "0") break;
      if (Number(seg) > 255) break;
      parts.push(seg);
      dfs(start + len);
      parts.pop();
    }
  }
  dfs(0);
  out.sort();
  return out;
}
